public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Both Y and N must be positive integers.");
    }

    int count = 0;
    int year = Y + 1;

    while (count < N) {
        if (isLeapYear(year)) {
            count++;
        }
        if (count < N) {
            year++;
        }
    }

    return year;
}

/**
 * Checks if the given year is a leap year.
 *
 * @param year the year to check
 * @return true if the year is a leap year, false otherwise
 */
private static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

public static int calculateTimeNeeded(int N) {
    if (N <= 1) {
        return 0; // No time needed for 0 or 1 person
    }
    if (N == 2) {
        return 1; // Only one swap needed for 2 people
    }
    // For more than 2 people, the time needed is (N-1) minutes
    return 2 * (N - 2);
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, result);
        used[i] = false;
        current.remove(current.size() - 1);
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    // Check all substrings of the first string
    String first = strings.get(0);
    for (int i = 0; i < first.length(); i++) {
        for (int j = i + 1; j <= first.length(); j++) {
            String substring = first.substring(i, j);
            String inverse = new StringBuilder(substring).reverse().toString();

            boolean allContain = true;
            for (String str : strings) {
                if (!(str.contains(substring) || str.contains(inverse))) {
                    allContain = false;
                    break;
                }
            }

            if (allContain && substring.length() > maxLength) {
                maxLength = substring.length();
            }
        }
    }

    return maxLength;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int numDeposits = 0;
    int numRows = grid.length;
    int numCols = grid[0].length;
    boolean[][] visited = new boolean[numRows][numCols];

    for (int row = 0; row < numRows; row++) {
        for (int col = 0; col < numCols; col++) {
            if (grid[row][col] == '@' && !visited[row][col]) {
                dfs(grid, visited, row, col);
                numDeposits++;
            }
        }
    }

    return numDeposits;
}

private static void dfs(char[][] grid, boolean[][] visited, int row, int col) {
    int[] rowDirections = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] colDirections = {-1, 0, 1, -1, 1, -1, 0, 1};

    visited[row][col] = true;

    for (int d = 0; d < 8; d++) {
        int newRow = row + rowDirections[d];
        int newCol = col + colDirections[d];

        if (newRow >= 0 && newRow < grid.length && newCol >= 0 && newCol < grid[0].length && grid[newRow][newCol] == '@' && !visited[newRow][newCol]) {
            dfs(grid, visited, newRow, newCol);
        }
    }
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("The number of triangles must be non-negative.");
    }
    // When N triangles are added, each new triangle can intersect with all previous ones
    // creating 2 new regions for each intersection plus 2 more regions.
    // So, the number of regions formed by N triangles is given by the formula:
    // R(N) = 2 + 2 * N + N * (N - 1)
    // Simplifying the formula, we get:
    // R(N) = N * N + N + 2
    return N * N + N + 2;
}

