public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canReach = dfs(start[0], start[1], end[0], end[1], visited, paths, n);
    return canReach ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, boolean[][] visited, int[][] paths, int n) {
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;

    for (int[] path : paths) {
        if (path[0] == x && path[1] == y) {
            if (dfs(path[2], path[3], endX, endY, visited, paths, n)) {
                return true;
            }
        } else if (path[2] == x && path[3] == y) {
            if (dfs(path[0], path[1], endX, endY, visited, paths, n)) {
                return true;
            }
        }
    }
    return false;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "Invalid input";
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        count1[c - 'A']++;
    }

    for (char c : word2.toCharArray()) {
        count2[c - 'A']++;
    }

    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(count1[i], count2[i]);
    }

    int totalLength = word1.length() + word2.length();

    if (totalLength == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(common, totalLength);
    common /= gcd;
    totalLength /= gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + (common == 0 ? "0" : (common == totalLength ? "1" : common + "/" + totalLength));
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] dateParts = date.split(" ");
        if (dateParts.length != 3) {
            return "Invalid date format";
        }

        int month = Integer.parseInt(dateParts[0]);
        int day = Integer.parseInt(dateParts[1]);
        int year = Integer.parseInt(dateParts[2]);

        String[] months = {
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };

        if (month < 1 || month > 12) {
            return "Invalid month";
        }
        if (day < 1 || day > 31) {
            return "Invalid day";
        }

        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.set(year, month - 1, day);

        String[] weekdays = {
            "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"
        };

        int dayOfWeek = calendar.get(java.util.Calendar.DAY_OF_WEEK);
        String weekdayName = weekdays[dayOfWeek - 1];
        String monthName = months[month - 1];

        return monthName + " " + day + ", " + year + " is a " + weekdayName;
    } catch (NumberFormatException e) {
        return "Invalid date format";
    }
}

public int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> numMap = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (numMap.containsKey(complement)) {
            return new int[]{numMap.get(complement), i};
        }
        numMap.put(nums[i], i);
    }
    throw new IllegalArgumentException("No two sum solution");
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }

    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (nums[mid] == target) {
            return mid;
        }

        // Determine which side is properly sorted
        if (nums[left] <= nums[mid]) {
            // Left side is sorted
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            // Right side is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int n = arr.length;
    int removeCount = n / 20; // 5% of elements to remove from both ends

    // Sort the array
    Arrays.sort(arr);

    // Calculate the sum of the remaining elements
    double sum = 0;
    int count = n - 2 * removeCount;
    for (int i = removeCount; i < n - removeCount; i++) {
        sum += arr[i];
    }

    // Calculate and return the mean
    return sum / count;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = (num % k + k) % k; // Handle negative numbers
        remainderCount[remainder]++;
    }

    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] tree = new List[n];
    for (int i = 0; i < n; i++) {
        tree[i] = new ArrayList<>();
    }

    for (int[] edge : edges) {
        tree[edge[0]].add(edge[1]);
        tree[edge[1]].add(edge[0]);
    }

    return helper(0, -1, tree, hasApple);
}

private int helper(int node, int parent, List<Integer>[] tree, boolean[] hasApple) {
    int totalTime = 0;

    for (int child : tree[node]) {
        if (child == parent) continue;
        int childTime = helper(child, node, tree, hasApple);
        if (childTime > 0 || hasApple[child]) {
            totalTime += childTime + 2;
        }
    }

    return totalTime;
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    boolean forward = true;

    while (result.length() < s.length()) {
        if (forward) {
            for (int i = 0; i < 26; i++) {
                if (count[i] > 0) {
                    result.append((char) ('a' + i));
                    count[i]--;
                }
            }
        } else {
            for (int i = 25; i >= 0; i--) {
                if (count[i] > 0) {
                    result.append((char) ('a' + i));
                    count[i]--;
                }
            }
        }
        forward = !forward;
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][sum + 1][n + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = n / 2; j >= 0; j--) {
            for (int k = sum; k >= num; k--) {
                for (int l = i - 1; l >= 0; l--) {
                    if (dp[j][k][l]) {
                        dp[j + 1][k + num][i] = true;
                    }
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            int targetSum = sum * i / n;
            if (dp[i][targetSum][n]) {
                return true;
            }
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must contain at least two elements.");
    }

    int[] dp = new int[cost.length + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= cost.length; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[cost.length];
}

public int uniqueMorseRepresentations(String[] words) {
    String[] morseCode = {
        ".-","-...","-.-.","-..",".","..-.","--.","....","..",".---",
        "-.-",".-..","--","-.","---",".--.","--.-",".-.","...","-",
        "..-","...-",".--","-..-","-.--","--.."
    };

    Set<String> uniqueTransformations = new HashSet<>();

    for (String word : words) {
        StringBuilder morseWord = new StringBuilder();
        for (char c : word.toCharArray()) {
