public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        ones = (ones ^ num) & ~twos;
        twos = (twos ^ num) & ~ones;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        findSteppingNumbersHelper(i, i, low, high, result);
    }

    Collections.sort(result);
    return result;
}

private static void findSteppingNumbersHelper(int current, int lastDigit, int low, int high, List<Integer> result) {
    for (int nextDigit = lastDigit - 1; nextDigit <= lastDigit + 1; nextDigit += 2) {
        if (nextDigit >= 0 && nextDigit <= 9) {
            int nextNumber = current * 10 + nextDigit;
            if (nextNumber <= high) {
                if (nextNumber >= low) {
                    result.add(nextNumber);
                }
                findSteppingNumbersHelper(nextNumber, nextDigit, low, high, result);
            }
        }
    }
}

