    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    // Arrays to store the length of consecutive 1s in each direction
    int[][] horizontal = new int[rows][cols];
    int[][] vertical = new int[rows][cols];
    int[][] diagonal = new int[rows][cols];
    int[][] antiDiagonal = new int[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;

                // Vertical
                vertical[i][j] = (i > 0 ? vertical[i - 1][j] : 0) + 1;

                // Diagonal
                diagonal[i][j] = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;

                // Anti-diagonal
                antiDiagonal[i][j] = (i > 0 && j < cols - 1 ? antiDiagonal[i - 1][j + 1] : 0) + 1;

                // Update maxLength
                maxLength = Math.max(maxLength, horizontal[i][j]);
                maxLength = Math.max(maxLength, vertical[i][j]);
                maxLength = Math.max(maxLength, diagonal[i][j]);
                maxLength = Math.max(maxLength, antiDiagonal[i][j]);
            }
        }
    }

    return maxLength;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder result = new StringBuilder();
    String numberStr = Integer.toString(n);
    int length = numberStr.length();

    for (int i = 0; i < length; i++) {
        result.append(numberStr.charAt(i));
        // Add a dot if this is not the last digit and there are at least three more digits left
        if (i < length - 1 && (length - i - 1) % 3 == 0) {
            result.append('.');
        }
    }

    return result.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    boolean[] used = new boolean[A.length];
    int[] count = new int[1];
    backtrack(A, used, new int[A.length], 0, count);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, int[] current, int depth, int[] count) {
    if (depth == A.length) {
        count[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            if (depth == 0 || isPerfectSquare(current[depth - 1] + A[i])) {
                used[i] = true;
                current[depth] = A[i];
                backtrack(A, used, current, depth + 1, count);
                used[i] = false;
            }
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] stack = new int[heights.length];
    int top = -1;

    for (int i = 0; i < heights.length; i++) {
        while (top != -1 && heights[i] < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int left = top == -1 ? -1 : stack[top];
            maxArea = Math.max(maxArea, (i - left - 1) * height);
        }
        stack[++top] = i;
    }

    while (top != -1) {
        int height = heights[stack[top--]];
        int left = top == -1 ? -1 : stack[top];
        maxArea = Math.max(maxArea, (heights.length - left - 1) * height);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];
        if ((r + c) % 2 == 0) { // moving up
            if (c == cols - 1) {
                r++;
            } else if (r == 0) {
                c++;
            } else {
                r--;
                c++;
            }
        } else { // moving down
            if (r == rows - 1) {
                c++;
            } else if (c == 0) {
                r++;
            } else {
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;

    // Find the rightmost digit that is smaller than the digit next to it
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of (i-th digit) that is larger than digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits after (i+1)-th place
    Arrays.sort(digits, i + 1, digits.length);

    // Convert the char array back to an integer
    long result = Long.parseLong(new String(digits));

    // Check if the result is within the bounds of integer
    if (result > Integer.MAX_VALUE) {
        return -1;
    }

    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }

    List<String> result = new ArrayList<>();
    if (n == 1) {
        return new ArrayList<>(Arrays.asList("0", "1", "8"));
    }
    if (n == 2) {
        return new ArrayList<>(Arrays.asList("11", "69", "88", "96"));
    }

    String[] pairs = {"00", "11", "69", "88", "96"};
    List<String> middle = centerSymmetricNumbers(n - 2);

    for (String s : middle) {
        for (int i = 1; i < pairs.length; i++) { // Skip "00" for the outermost layer
            result.add(pairs[i].charAt(0) + s + pairs[i].charAt(1));
        }
        if (n > 3) { // Only add "0" pairs for non-boundary layers
            result.add(pairs[0].charAt(0) + s + pairs[0].charAt(1));
        }
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Input must be a 2D array with exactly 3 points, each having 2 coordinates.");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    // Area = 0.5 * | x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2) |
    // If the area is 0, the points are collinear and do not form a boomerang
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int index2 = 0, index3 = 0, index5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            index2++;
            nextMultipleOf2 = uglyNumbers[index2] * 2;
        }

        if (nextUglyNumber == nextMultipleOf3) {
            index3++;
            nextMultipleOf3 = uglyNumbers[index3] * 3;
        }

        if (nextUglyNumber == nextMultipleOf5) {
            index5++;
            nextMultipleOf5 = uglyNumbers[index5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    char prevChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar == prevChar) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
        prevChar = currentChar;
    }

    return Math.max(maxEnergy, currentEnergy);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort((a, b) -> String.valueOf(a).compareTo(String.valueOf(b)));
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> counts = new LinkedHashMap<>();
    for (int num : nums) {
        counts.put(num, counts.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }

    for (int i = 1; i <= n; i++) {
        int j = 1;
        while (j * j <= i) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
            j++;
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        StringBuilder reversedWord = new StringBuilder(word).reverse();
        result.append(reversedWord);

        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}
